    for (int i = 0; i < g.levelCount; i++) {
      drawLevelCard(g, i);
    }

    int openLevels = Math.min(g.unlocked, g.levelCount);
    text("LEVEL TERBUKA " + openLevels + "/" + g.levelCount, 12, 21, COL_TEXT, fTiny);
    box(12, 27, 296, 3, COL_PANEL_DARK);
